pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract InvMutTest is Test {
    demo c;
    function setUp() public { c = new demo(); }

    function testFuzz_property(address from, address tosRecipient, uint256 v, uint256 len) public {
        uint256 n = bound(len, 1, 8);

        address[] memory _tos = new address[](n);
        for (uint i = 0; i < n; i++) {
            _tos[i] = tosRecipient;
        }

        bool ok;
        try c.transfer(from, tosRecipient, _tos, v) returns (bool ret) {
            ok = ret;
        } catch {
            ok = false;
        }

        assertTrue(ok);
    }
}
